    this.oilRegen = 3.5;          // per second, while not burning
    this.burnDrain = 9;           // per second, while burning
    this.dartCost = 6;
    this.pulseCost = 18;
    this.burnRadius = 4.2;        // metres the beam scorches
    this.burnRate = 34;           // damage per second inside the beam
    this.pulseRadius = 9;
