    const body = new THREE.Mesh(new THREE.ConeGeometry(0.55, 1.5, 7), bodyMat);
    body.position.y = 0.75;
    this.group.add(body);
    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.26, 8, 8),
      new THREE.MeshLambertMaterial({ color: 0x4a3d30 }),
    );
