    if (keys.has('s')) dir.z += 1;
    if (keys.has('a')) dir.x -= 1;
    if (keys.has('d')) dir.x += 1;
    const camYaw = Math.atan2(
      camera.position.x - this.pos.x,
      camera.position.z - this.pos.z,
